#include "platform.h"
#include "games.h"
// One game program, two ways to play it:
// - short (GAME_SESSION 0): GAME_ACTIONS presses from a prepared board
//   (GAME_PRESET), for a scenario that reaches the game's key event;
// - long (GAME_SESSION 1): SESSION_STEPS updates from a computer player's
//   script (session.h, generated by tools/rv32im/build-guests.py), with
//   restarts between episodes.
#ifndef GAME_KIND
#define GAME_KIND 1
#endif
#ifndef GAME_ACTIONS
#define GAME_ACTIONS 3
#endif
#ifndef GAME_PRESET
#define GAME_PRESET 0
#endif
#ifndef GAME_AUTOTICKS
#define GAME_AUTOTICKS 0
#endif
#ifndef GAME_SESSION
#define GAME_SESSION 0
#endif
#if GAME_SESSION
#include "session.h"
#endif
static Game game;
// The colors of the cells drawn last; the largest board has 8 x 16 cells.
static uint8_t previous[128];
#ifdef CIRCUITSIM_GUEST_REFERENCE
const Game *guest_reference_game_state(void){return &game;}
#endif
static const uint8_t colors[12]={0,224,28,3,252,227,31,124,156,208,180,255};
static const char *const names[6]={"bring-up","2048","sokoban","snake","pong","tetris"};

// Cell size in pixels, from the display's geometry. On the 64 x 48 screen:
// 2048 16 x 12, Sokoban and Snake 6 x 6, Pong 2 x 3, Tetris 4 x 3.
static unsigned cw,ch;
static void geometry(void) {
    const unsigned w=display_width(),h=display_height();
    if(GAME_KIND==GAME_2048){cw=w/4;ch=h/4;}
    else if(GAME_KIND==GAME_PONG){cw=w/32;ch=h/16;}
    else if(GAME_KIND==GAME_TETRIS){ch=h/16;cw=ch+1;}
    else cw=ch=(w<h?w:h)/8;
}

// 3 x 5 digits, written straight into video memory.
static const uint16_t digits[10]={0x7b6f,0x2492,0x73e7,0x73cf,0x5bc9,0x79cf,0x79ef,0x7249,0x7bef,0x7bcf};
static void number(unsigned value,unsigned x,unsigned y) {
    const unsigned stride=display_stride(),width=display_width();
    unsigned divisor=1;while(value/divisor>=10)divisor*=10;
    for(;divisor&&x+3<=width;divisor/=10,x+=3){
        const uint16_t glyph=digits[(value/divisor)%10];
        uint32_t row=VIDEO_BASE+y*stride+x;
        for(int yy=0;yy<5;++yy,row+=stride)for(int xx=0;xx<3;++xx)
            if(glyph&(1u<<(14-yy*3-xx)))io_write8(row+(uint32_t)xx,255);
    }
}
#ifdef LEDS_LEDS
// Machines with an LED panel: light one LED per snake segment (or point of
// score), and blink them when the game is lost.
static void show_leds(void) {
    unsigned n=GAME_KIND==GAME_SNAKE?game.length:game.score;
    if(n>16)n=16;
    io_write(LEDS_LEDS,n>=16?0xffffu:(1u<<n)-1u);
    io_write(LEDS_BLINK,game.status==GAME_LOST?3u:0u);
}
#else
static void show_leds(void) {}
#endif
static void render(void) {
    if(GAME_KIND==GAME_PONG){
        // Sprites: erase what moved, draw the ball and the paddles.
        static int old_left,old_right,old_x,old_y;static unsigned drawn;
        if(drawn){
            rect(old_x*cw,old_y*ch,cw,ch,0);
            if(old_left!=game.y)rect(cw,old_left*ch,cw,4*ch,0);
            if(old_right!=game.other)rect(30*cw,old_right*ch,cw,4*ch,0);
        }
        // Restore a paddle if the old ball could have covered its column.
        if(!drawn||old_left!=game.y||old_x==1)rect(cw,game.y*ch,cw,4*ch,colors[1]);
        if(!drawn||old_right!=game.other||old_x==30)rect(30*cw,game.other*ch,cw,4*ch,colors[2]);
        rect(game.ball_x*cw,game.ball_y*ch,cw,ch,colors[3]);
        old_left=game.y;old_right=game.other;old_x=game.ball_x;old_y=game.ball_y;drawn=1;
        show_leds();present();return;
    }
    const unsigned cols=GAME_KIND==GAME_2048?4:8;
    const unsigned rows=GAME_KIND==GAME_2048?4:GAME_KIND==GAME_TETRIS?16:8;
    // Only changed cells are redrawn (previous[] starts black).
    uint8_t board[128];game_board(&game,board);
    for(unsigned y=0,at=0;y<rows;++y)for(unsigned x=0;x<cols;++x,++at){
        const uint8_t v=board[at];if(previous[at]==v)continue;previous[at]=v;
        rect((int)(x*cw),(int)(y*ch),(int)cw,(int)ch,colors[v%12]);
        if(GAME_KIND==GAME_2048&&v)number(1u<<v,x*cw+1,y*ch+(ch-5)/2);
    }
    show_leds();present();
}

#if GAME_SESSION
static unsigned episode;
static uint32_t accumulated_score;
// Each episode starts with its own random seed (and Sokoban with its own puzzle).
static void session_init(void) {
    game_init(&game,GAME_KIND);
    game.seed=0x12345678u+episode*7919u;
#if GAME_KIND == 2
    if(episode>=SESSION_LEVELS){game.status=GAME_LOST;return;}
    for(unsigned i=0;i<64;++i)game.cells[i]=session_levels[episode][i];
    game.x=session_players[episode][0];game.y=session_players[episode][1];
#endif
}
#endif

static void prepare(void) {
#if GAME_SESSION
    session_init();
#else
    game_init(&game,GAME_KIND);
    // Prepared boards that reach the game's key event in a few presses.
#if GAME_PRESET == 1      /* 2048: four 2s in the top row; LEFT merges them */
    for(unsigned i=0;i<16;++i)game.cells[i]=0;
    for(unsigned i=0;i<4;++i)game.cells[i]=1;
#elif GAME_PRESET == 2    /* Tetris: the bottom row is missing four cells, an
                             I piece hangs above the gap */
    for(unsigned i=0;i<128;++i)game.cells[i]=0;
    for(unsigned i=0;i<4;++i)game.cells[120+i]=1;
    game.piece=0;game.rotation=0;game.x=4;game.y=8;
#elif GAME_PRESET == 3    /* Pong: the ball is one step from the right paddle */
    game.ball_x=29;game.ball_y=5;game.ball_dx=game.ball_dy=1;
#elif GAME_PRESET == 4    /* Snake: the head is one cell from the right wall */
    game.body_x[0]=6;game.body_x[1]=5;game.body_x[2]=4;
    game.food_x=0;game.food_y=0;
#elif GAME_PRESET == 5    /* Snake: food two cells ahead of the head */
    game.food_x=5;game.food_y=3;
#endif
#endif
}

int main(void) {
    volatile uint32_t *report=platform_report();
    console_write(names[GAME_KIND]);console_write("\n");
    geometry();prepare();
    // RST retains video memory, so startup clears the surface. previous[]
    // starts black, so black starting cells are not drawn twice.
    clear_screen(0);render();
    unsigned actions=0;
#if GAME_SESSION
    while(actions<SESSION_STEPS){
        if(!event_count())continue;
        uint32_t event=event_peek();event_pop();
        if(!(event&0x100u))continue;
        const unsigned button=event&31u;
        if(button==BUTTON_RESET){accumulated_score+=game.score;++episode;session_init();}
        else{
#if GAME_KIND == 3
            // Snake turns on a tap and moves on an update.
            if(button<4){game_action(&game,button,button_levels());continue;}
            if(button!=BUTTON_TICK)continue;
#elif GAME_KIND == 4
            if(button!=BUTTON_TICK)continue;
#endif
            game_action(&game,button,button_levels());
        }
        ++actions;render();
    }
    report[0]=0x4c47534du;report[4]=accumulated_score+game.score;
#else
    while(actions<GAME_ACTIONS){
        if(!event_count())continue;
        uint32_t event=event_peek();event_pop();
        if(!(event&0x100u))continue;
        game_action(&game,event&31u,button_levels());++actions;render();
    }
    // A finite guest-controlled rally: repeated rule and render updates
    // without waiting for further device events.
#if GAME_AUTOTICKS > 0
    for(unsigned i=0;i<GAME_AUTOTICKS;++i){game_action(&game,BUTTON_TICK,button_levels());++actions;render();}
#endif
    report[0]=0x4353474du;report[4]=game.score;
#endif
    // Report at a fixed reserved address: magic, ABI, game, updates, score,
    // final state, rule-state fingerprint, timer sample, input status.
    report[1]=1;report[2]=GAME_KIND;report[3]=actions;
    // Short runs skip the rule-state fingerprint (about 1,800 instructions);
    // their frames, score and final state are still checked.
    report[5]=game.status;report[6]=GAME_SESSION?game_fingerprint(&game):0;
    report[7]=ticks();report[8]=io_read(BUTTONS_STATUS);
    io_order();console_write("done\n");return 0;
}
